SELECT AVG(amount_eur) AS average_invoice_amount_eur
FROM fct_invoices
WHERE status <> 'void';

SELECT CAST(COALESCE(SUM(amount_eur), 0.00) AS DECIMAL(38,2)) AS cash_collected_eur
FROM fct_revenue_daily
WHERE revenue_date BETWEEN DATE '2026-07-24' AND DATE '2026-10-22';

SELECT CAST(COALESCE(SUM(amount_eur), 0) AS DECIMAL(38,2)) AS collected_revenue_ytd_eur
FROM fct_revenue_daily
WHERE revenue_date BETWEEN DATE '2026-01-01' AND DATE '2026-10-22';
